# Factory defaults of the AF-target cells from the bank-7 registration
# descriptor. Width is (key & 3) or 4, the rule in AFON-MENU-RESEARCH and
# the T2 walker. Payloads are the descriptor bytes, not a session's RAM.
# Do not edit this file after it has run.
import json
import struct
from pathlib import Path

ROOT = Path('.')
IMAGE = (ROOT / 'inputs/00_0100_50000020.decoded.bin').read_bytes()
BASE = 0x60021020
TABLE = 0x600E4BEC
END_KEY = 0x6011FE20
LIVE_BASE = 0x62920700
KEYS = [0x99A1, 0x9A41, 0x5962, 0x1DD1, 0x84D1, 0x88B2, 0x90D1, 0x5A11, 0x1DE1, 0x1DF1, 0x5B82]
PATTERNS = {
    'session-99a1': bytes([2, 0, 2, 0, 2, 0, 5, 5]),
    'session-1dd1-head': bytes([27, 39, 3, 3, 3, 3, 3, 3, 3, 3]),
    'session-5a11': bytes([1, 1, 1, 0, 1, 0, 0, 0, 0, 1, 1]),
    'pos-526-six': struct.pack('<6H', *([526] * 6)),
}


def u16(off):
    return struct.unpack_from('<H', IMAGE, off - BASE)[0]


def walk(start):
    addr = start
    live = 8
    rows = []
    for _ in range(5000):
        key = u16(addr)
        if key == 0:
            return rows, addr, live
        count = u16(addr + 2)
        width = (key & 3) or 4
        payload_len = count * width
        raw = IMAGE[addr + 4 - BASE: addr + 4 - BASE + payload_len]
        if live % width:
            live += width - (live % width)
        rows.append({
            'key': key,
            'record': addr,
            'count': count,
            'width': width,
            'payload': raw.hex(),
            'live': LIVE_BASE + live,
        })
        live += payload_len
        addr = (addr + 4 + payload_len + 3) & ~3
    raise SystemExit('registration walk did not reach a zero key')


rows, end, live_end = walk(TABLE)
if end != END_KEY:
    raise SystemExit(f'zero key at {end:#x}, expected {END_KEY:#x}')
by_key = {}
for row in rows:
    by_key.setdefault(row['key'], []).append(row)
wanted = []
for key in KEYS:
    hits = by_key.get(key, [])
    wanted.append({'key': f'{key:#x}', 'records': [
        {**hit, 'key': f'{hit["key"]:#x}', 'record': f'{hit["record"]:#x}', 'live': f'{hit["live"]:#x}'}
        for hit in hits
    ]})
checks = {
    'records': len(rows),
    'zero_key': f'{end:#x}',
    'live_end': f'{LIVE_BASE + live_end:#x}',
    'known_5b82': any(hit['record'] == 0x600E5874 and hit['count'] == 16 and hit['width'] == 2 for hit in by_key.get(0x5B82, [])),
    'known_99a1_zeros': any(hit['record'] == 0x6011EBDC and hit['payload'] == '00' * 8 for hit in by_key.get(0x99A1, [])),
}
patterns = {}
for name, needle in PATTERNS.items():
    found = []
    start = 0
    while len(found) < 12:
        j = IMAGE.find(needle, start)
        if j < 0:
            break
        found.append(f'{BASE + j:#x}')
        start = j + 1
    patterns[name] = {'hits_capped': found, 'more': IMAGE.find(needle, start) >= 0}
report = {'checks': checks, 'keys': wanted, 'image_patterns': patterns}
out = ROOT / 'work/out/factory-defaults-l0.json'
out.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'checks': checks, 'keys': {row['key']: row['records'] for row in wanted}, 'patterns': patterns}, indent=2))
if not checks['known_5b82'] or not checks['known_99a1_zeros']:
    raise SystemExit(1)
